def guards() -> None:
    op.execute("""
    CREATE FUNCTION research_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN RAISE EXCEPTION 'immutable research artifact'; END $$;
    CREATE FUNCTION research_mission_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
      IF (NEW.id,NEW.owner_id,NEW.topic_id,NEW.question,NEW.run_sequence,
          NEW.baseline_result_id,NEW.inputs)
         IS DISTINCT FROM
         (OLD.id,OLD.owner_id,OLD.topic_id,OLD.question,OLD.run_sequence,
          OLD.baseline_result_id,OLD.inputs)
      THEN RAISE EXCEPTION 'frozen mission inputs'; END IF;
      IF OLD.frozen AND NOT NEW.frozen THEN RAISE EXCEPTION 'frozen evidence'; END IF;
      IF NEW.status <> OLD.status AND NOT (
          (OLD.status='QUEUED' AND NEW.status IN ('RUNNING','CANCELLED')) OR
          (OLD.status='RUNNING' AND NEW.status IN ('COMPLETED','PARTIAL','FAILED','CANCELLED')))
      THEN RAISE EXCEPTION 'invalid mission transition'; END IF;
      RETURN NEW;
    END $$;
    CREATE TRIGGER research_mission_guard BEFORE UPDATE ON research_mission
    FOR EACH ROW EXECUTE FUNCTION research_mission_guard();
    CREATE FUNCTION research_evidence_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    DECLARE m research_mission; c content_chunk;
    BEGIN
      SELECT * INTO m FROM research_mission WHERE id=NEW.mission_id AND owner_id=NEW.owner_id
      FOR UPDATE;
      IF m.id IS NULL OR m.frozen OR m.status <> 'RUNNING'
      THEN RAISE EXCEPTION 'evidence frozen or inactive'; END IF;
      SELECT * INTO c FROM content_chunk WHERE id=NEW.chunk_id AND owner_id=NEW.owner_id;
      IF c.id IS NULL OR c.content_id<>NEW.content_id OR c.extraction_id<>NEW.extraction_id
         OR (NEW.payload->>'id')::uuid<>NEW.id
         OR (NEW.payload->>'mission_id')::uuid<>NEW.mission_id
         OR (NEW.payload->>'owner_id')::uuid<>NEW.owner_id
         OR (NEW.payload->>'content_id')::uuid<>NEW.content_id
         OR (NEW.payload->>'extraction_id')::uuid<>NEW.extraction_id
         OR (NEW.payload->>'chunk_id')::uuid<>NEW.chunk_id
         OR (NEW.payload->>'start')::int<>c.start OR (NEW.payload->>'end')::int<>c."end"
         OR (NEW.payload->>'page')::int IS DISTINCT FROM c.page
         OR NEW.payload->>'quote'<>c.text OR NEW.payload->>'text_hash'<>c.text_hash
      THEN RAISE EXCEPTION 'invalid evidence locator'; END IF;
      RETURN NEW;
    END $$;
    CREATE TRIGGER research_evidence_guard BEFORE INSERT ON research_evidence
    FOR EACH ROW EXECUTE FUNCTION research_evidence_guard();
    """)
    for table in ("research_evidence", "research_result", "research_proposal", "research_stage"):
        op.execute(
            f"CREATE TRIGGER {table}_immutable BEFORE UPDATE OR DELETE ON {table} "
            "FOR EACH ROW EXECUTE FUNCTION research_immutable()"
        )
